WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_p_repeat'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '重复元素排列', 'kp-pc-p-repeat', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "重复元素排列"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果有 M 个完全一样的元素参与排队，总排列数必须除以 M! 来去重。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“用 3 个红球和 2 个白球排成一排，有几种排法？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "katexBlock", "attrs": {"content": "N = \\frac{5!}{3! \\times 2!} = 10 \\text{ 种}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "先把所有球当成不一样的人，全排列是 5!。但 3 个红球互相换位置不会产生新排法，必须除以 3! 抵消。2 个白球同理。"}]}]}$$ AS jsonb), NULL, '重复元素排列的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "重复元素排列"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_p_repeat", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
